import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DdtnLau3.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"A shareable, runnable AI workspace","tagline":"Powered by an evolvable Harness.","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"Get Started","link":"/guide/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function o(r,e,h,l,p,d){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h2 id="what-is-piwork" tabindex="-1">What is Piwork? <a class="header-anchor" href="#what-is-piwork" aria-label="Permalink to &quot;What is Piwork?&quot;">​</a></h2><p>Piwork packages a runnable AI workspace into a portable unit called a <strong>Work</strong>. Keep the applications, files, conversation history, and execution environment together, then export them and continue on another Piwork installation.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Role</th></tr></thead><tbody><tr><td><a href="/piwork/concepts/work.html">Work</a></td><td><strong>The workspace.</strong> Holds the environment and its durable state.</td></tr><tr><td><a href="/piwork/concepts/service.html">Service</a></td><td><strong>The capability.</strong> Runs an application, API, or other container service.</td></tr><tr><td><a href="/piwork/concepts/harness.html">Harness</a></td><td><strong>The intelligence.</strong> Uses models, tools, and workspace-specific instructions to understand and operate the Work.</td></tr></tbody></table><p>The Harness can help build and change the workspace it runs in. Its instructions, Skills, packages, and verified experience can evolve with that Work.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>Create → Run → Evolve → Export → Share → Import → Continue</strong></p><p>Export a stopped Work as a <code>.work</code> file. Import it into a compatible installation and start it explicitly. The target supplies its own model credentials.</p><h2 id="demo-kanban-work" tabindex="-1">Demo: Kanban Work <a class="header-anchor" href="#demo-kanban-work" aria-label="Permalink to &quot;Demo: Kanban Work&quot;">​</a></h2><p>A board, its data, an application Service, and a Harness that helps build and operate it form one workspace. <a href="/piwork/demo/kanban.html">Read the Kanban walkthrough</a>. A downloadable demo and recording are still being prepared.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p>If you can run Docker, you can try Piwork. You need a Linux x86-64 Core host, Docker Engine 28+, Compose 2.24+, and a model provider account. Linux and Windows Docker Desktop clients are supported.</p><p><a href="/piwork/guide/installation.html">Download and configure the Docker setup files</a>, then start Core:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.core.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span></span></code></pre></div><p><a href="/piwork/guide/quick-start.html">Open Desktop and run your first Work</a>. Questions and feedback belong in <a href="https://github.com/pphboy/piwork/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</p>`,14)])])}const u=a(n,[["render",o]]);export{c as __pageData,u as default};
